SELECT tertile, COUNT(*) AS admission_count, (SELECT COUNT(*) FROM tertiles WHERE min_meds <= med_count AND max_meds >= med_count) AS med_score_count, (SELECT COUNT(*) FROM tertiles WHERE min_pH <= pH AND max_pH >= pH) AS pH_score_count, (SELECT COUNT(*) FROM tertiles WHERE min_lactate <= lactate AND max_lactate >= lactate) AS lactate_score_count, (SELECT COUNT(*) FROM tertiles WHERE min_mortality <= mortality AND max_mortality >= mortality) AS mortality_score_count, (SELECT COUNT(*) FROM tertiles WHERE min_transfers <= recent_transfers AND max_transfers >= recent_transfers) AS recent_transfer_count FROM tertiles GROUP BY tertile;